import json as _j
async def main(args):
    p = args.params
    schemas = list(p.get("official") or [])
    rep = p.get("report")
    try:
        schemas.append(_j.loads(rep) if isinstance(rep, str) else rep)
    except Exception as e:
        return {"tools": schemas, "err": str(e)[:120]}
    return {"tools": schemas}

import json as _j
async def main(args):
    """report_hits 调用 → 结构化 answer。schema 强约束下 arguments 即最终结果：
    {relevant: bool, hits: [{page, excerpt}]}。截到 3 条防御。"""
    tc = ((args.params.get("tool_calls") or [{}]) or [{}])[0]
    a = (tc.get("function") or {}).get("arguments") or tc.get("arguments") or {}
    if isinstance(a, str):
        try:
            a = _j.loads(a)
        except Exception:
            a = {}
    if not isinstance(a, dict):
        a = {}
    hits = []
    for h in (a.get("hits") or [])[:3]:
        if isinstance(h, dict) and str(h.get("page") or "").strip():
            hits.append({"page": str(h["page"]).strip(),
                         "excerpt": str(h.get("excerpt") or "").strip()[:160]})
    return {"answer": {"relevant": bool(a.get("relevant")), "hits": hits}}

async def main(args):
    """continue 单 result 模型：组装本轮 object（未走分支的字段为 None，与旧多字段行为一致）"""
    p = args.params
    return {"result": {"resp": p.get("resp"), "tool": p.get("tool"),
                       "report": p.get("report"), "fallback": p.get("fallback")}}

async def main(args):
    """结构化 answer → 注入文本。relevant=false / hits空 → NO_WIKI_RELEVANT（下游 contains 判官短路）；
    true → 「页面路径：原文摘录」行拼接（≤500字）。"""
    a = args.params.get("answer") or {}
    if isinstance(a, str):                     # 兜底：旧格式字符串直接透传
        return {"text": a}
    hits = a.get("hits") or []
    if not a.get("relevant") or not hits:
        return {"text": "NO_WIKI_RELEVANT"}
    lines = []
    for h in hits[:3]:
        p = str(h.get("page") or "?").strip()
        e = str(h.get("excerpt") or "").strip()[:160]
        if p and e:
            lines.append(f"{p}：{e}")
    return {"text": ("\n".join(lines) or "NO_WIKI_RELEVANT")[:500]}
